/** PATCH pixi-load (flicker preto no mapa do Barão): ver tools/as3-to-ts/patches/game/objects/SimpleObject.ts.json */
__stopAtLastFrame(mc: MovieClip): void {
  var onFrame = (): void => {
    if (!mc || this.m_movie !== mc) {
      mc?.removeEventListener(Event.ENTER_FRAME, onFrame);
      return;
    }
    if (mc.currentFrame >= mc.totalFrames) {
      mc.stop();
      mc.removeEventListener(Event.ENTER_FRAME, onFrame);
    }
  };
  mc.addEventListener(Event.ENTER_FRAME, onFrame);
}
